mesSim(document.getElementById("sim-l66"),Object.assign({id:"l66"},{kind:"db",title:"Bảng sự kiện và thời lượng",sub:"end_ts trống = sự kiện đang mở. Ràng buộc no_overlap chặn sự kiện chồng nhau của cùng một máy.",show:"state_event",tables:[{name:"state_event",cols:[{n:"machine_id",ty:"text",nn:1},{n:"state",ty:"text",nn:1,check:"state in ('RUNNING','IDLE','DOWN','NO_DATA')"},{n:"start_ts",ty:"timestamptz",nn:1},{n:"end_ts",ty:"timestamptz"},{n:"fault_code",ty:"int"},{n:"reason_id",ty:"text"}],
  exclude:{key:"machine_id",start:"start_ts",end:"end_ts",name:"no_overlap"},
  rows:[{machine_id:"L1-M1",state:"RUNNING",start_ts:"2026-11-12 06:00",end_ts:"2026-11-12 09:00"},{machine_id:"L1-M1",state:"DOWN",start_ts:"2026-11-12 09:00",end_ts:"2026-11-12 09:40",fault_code:12},
   {machine_id:"L1-M1",state:"RUNNING",start_ts:"2026-11-12 09:40",end_ts:"2026-11-12 12:30"},{machine_id:"L1-M1",state:"IDLE",start_ts:"2026-11-12 12:30",end_ts:"2026-11-12 12:50"},{machine_id:"L1-M1",state:"RUNNING",start_ts:"2026-11-12 12:50",end_ts:"2026-11-12 14:00"}]}],
 sql:"SELECT state, sum(extract(epoch FROM (end_ts - start_ts))) / 60 AS phut\nFROM state_event\nWHERE machine_id = 'L1-M1'\nGROUP BY state ORDER BY phut DESC;",
 samples:[{l:"Chồng lấn",sql:"INSERT INTO state_event (machine_id, state, start_ts, end_ts)\nVALUES ('L1-M1','IDLE','2026-11-12 09:30','2026-11-12 09:50');"}],
 tasks:[{t:"Chạy truy vấn thời lượng: RUNNING bao nhiêu phút?",ok:"420 phút: chưa trừ giờ nghỉ 10:00–10:30 (Bài 67 cắt theo kế hoạch còn 390).",check:(s,c)=>c.has("sql",e=>e.ok&&e.rows.some(r=>r[0]==="RUNNING"&&Math.abs(r[1]-420)<0.01))},
  {t:"Thử ghi IDLE 09:30–09:50 chồng lên DOWN.",check:(s,c)=>c.has("sql",e=>/exclusion/.test(e.err||""))},
  {t:"Thêm một sự kiện đang mở RUNNING từ 14:00 cho L1-M1, rồi chạy lại truy vấn thời lượng.",hint:"end_ts NULL thì end_ts − start_ts là NULL: sum bỏ qua. Dùng coalesce(end_ts, now()) nếu muốn tính tới hiện tại.",ok:"Sự kiện mở không có thời lượng tới khi đóng; truy vấn thật dùng coalesce hoặc upper_inf.",check:s=>s.rows("state_event").some(r=>r.end_ts==null)}]}));

